#!/usr/bin/env python3
"""Seed the CapDev star schema from the dataset generated by db/seed.py.

The legacy seed is run against a temporary SQLite file, so this script never
creates or replaces ready.db. The target database defaults to capdev_portal.db.

Usage:
    python db/seed_capdev_portal_2.py
    python db/seed_capdev_portal_2.py --db db/capdev_portal_test.db
"""
from __future__ import annotations

import argparse
import importlib.util
import json
import re
import sqlite3
import tempfile
from contextlib import closing
from datetime import date, datetime, timezone
from pathlib import Path
from typing import Any

import seed_capdev_portal as target_seed

HERE = Path(__file__).resolve().parent
SCHEMA_PATH = HERE / "capdev_portal_schema.sql"
COMPAT_PATH = HERE / "capdev_portal_compat_views.sql"
DEFAULT_DB_PATH = HERE / "capdev_portal.db"
SNAPSHOT_DATE = "2026-09-01"
RULE_VERSION = "READY-v0.2-seed"

PROGRAM_CODE_MAP = {
    "FDE": "FDE_CORE",
    "RDE": "RDE_WORKSHOP",
}
PROGRAM_STATUS_MAP = {
    "completed": "Completed",
    "enrolled": "In Progress",
    "nominated": "Nominated",
    "not_enrolled": "Not Started",
}
TRAINING_STATUS_MAP = {
    "completed": "Completed",
    "in_progress": "In Progress",
    "not_started": "Not Started",
}
CERT_STATUS_MAP = {
    "earned": "Earned",
    "in_progress": "In Progress",
    "planned": "Planned",
    "expired": "Expired",
}


def date_key(value: str | None) -> int | None:
    if not value:
        return None
    return int(value[:10].replace("-", ""))


def rows(connection: sqlite3.Connection, query: str, *parameters: Any) -> list[sqlite3.Row]:
    return connection.execute(query, parameters).fetchall()


def make_legacy_database(path: Path) -> None:
    seed_path = HERE / "seed.py"
    spec = importlib.util.spec_from_file_location("_capdev_legacy_seed", seed_path)
    if spec is None or spec.loader is None:
        raise RuntimeError(f"Could not load source seeder: {seed_path}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    module.DB_PATH = str(path)
    module.run()


def clear_target(connection: sqlite3.Connection) -> None:
    connection.execute("PRAGMA foreign_keys = OFF")
    target_seed.truncate_all(connection)


def seed_target(legacy: sqlite3.Connection, target: sqlite3.Connection) -> dict[str, int]:
    workers = rows(legacy, "SELECT * FROM workers ORDER BY id")
    skills = rows(legacy, "SELECT * FROM skills ORDER BY id")
    courses = rows(legacy, "SELECT * FROM training_catalog ORDER BY id")
    certifications = rows(legacy, "SELECT * FROM certifications ORDER BY id")
    programs = rows(legacy, "SELECT * FROM programs ORDER BY id")
    projects = {
        (person["project"], person["client"], person["industry_sector"])
        for person in workers
        if person["project"]
    }

    target_seed.seed_dim_date_range(target, date(2000, 1, 1), date(2040, 12, 31))

    capability_names = sorted({person["capability_area"] for person in workers if person["capability_area"]})
    capability_key: dict[str, int] = {}
    for name in capability_names:
        cursor = target.execute(
            "INSERT INTO dim_capability (CapabilityName) VALUES (?)", (name,)
        )
        capability_key[name] = cursor.lastrowid

    skill_key: dict[int, int] = {}
    for skill in skills:
        cursor = target.execute(
            "INSERT INTO dim_skill (SkillID, SkillName, SkillFamily) VALUES (?,?,?)",
            (f"SK-{skill['id']:03d}", skill["name"], skill["category"]),
        )
        skill_key[skill["id"]] = cursor.lastrowid

    course_key: dict[int, int] = {}
    for course in courses:
        cursor = target.execute(
            """INSERT INTO dim_course (
                   CourseCode, CourseName, Category, Provider, DurationHours,
                   URL, DueDate, Icon
               ) VALUES (?,?,?,?,?,?,?,?)""",
            (
                course["short_code"], course["name"], course["category"],
                course["provider"], course["duration_hours"], course["url"],
                course["due_date"], course["icon"],
            ),
        )
        course_key[course["id"]] = cursor.lastrowid

    certification_key: dict[int, str] = {}
    for certification in certifications:
        target.execute(
            """INSERT INTO dim_certification (
                   CertificationCode, CertificationName, Provider, Level,
                   StudyURL, PracticeURL, Badge
               ) VALUES (?,?,?,?,?,?,?)""",
            (
                certification["code"], certification["name"],
                certification["provider"], certification["level"],
                certification["study_url"], certification["practice_url"],
                certification["badge"],
            ),
        )
        certification_key[certification["id"]] = certification["code"]

    program_key: dict[int, str] = {}
    for program in programs:
        code = PROGRAM_CODE_MAP.get(program["code"], program["code"])
        target.execute(
            """INSERT INTO dim_program (ProgramCode, ProgramName, Description)
               VALUES (?,?,?)""",
            (code, program["name"], program["description"]),
        )
        program_key[program["id"]] = code

    project_key: dict[tuple[str, str | None, str | None], int] = {}
    for index, (name, client, industry) in enumerate(sorted(projects), start=1):
        slug = re.sub(r"[^A-Z0-9]+", "-", name.upper()).strip("-")
        cursor = target.execute(
            """INSERT INTO dim_project (
                   ProjectID, ProjectName, EngagementName, ClientName, Industry
               ) VALUES (?,?,?,?,?)""",
            (f"LEGACY-{slug}-{index}", name, name, client, industry),
        )
        project_key[(name, client, industry)] = cursor.lastrowid

    organization_rows = {
        (person["org5"], person["supervisory_org"], person["business_group"])
        for person in workers
    }
    for org5, org6, business_group in sorted(
        organization_rows, key=lambda value: tuple(item or "" for item in value)
    ):
        target.execute(
            """INSERT INTO dim_organization (
                   OrgLevel5, OrgLevel6, OrgLevel7, OrgLevel8,
                   BusinessGroup, Practice, Market, MarketUnit
               ) VALUES (?,?,NULL,NULL,?,NULL,NULL,NULL)""",
            (org5, org6, business_group),
        )

    legacy_worker_by_id = {person["id"]: person for person in workers}
    person_key: dict[str, int] = {}
    person_stage: dict[str, tuple[Any, ...]] = {}
    now = datetime.now(timezone.utc).isoformat(timespec="seconds")
    for person in workers:
        enterprise_id = person["employee_id"]
        people_lead = legacy_worker_by_id.get(person["people_lead_id"])
        people_lead_eid = people_lead["employee_id"] if people_lead else None
        full_name = f"{person['first_name']} {person['last_name']}".strip()
        level = f"L{person['management_level']}"
        cursor = target.execute(
            """INSERT INTO dim_person (
                   EnterpriseID, PersonnelNo, FullName, EmailAddress,
                   ManagementLevel, JobProfile, ProjectRole, EmploymentStatus,
                   ResourceType, ActivityType, JoinDate, HomeLocation,
                   CurrentLocation, Country, IsActive, PeopleLeadEID,
                   AvatarColor, EffectiveFrom, EffectiveTo, IsCurrent
               ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NULL,1)""",
            (
                enterprise_id, person["worker_id"], full_name, person["email"],
                level, person["job_profile"], None,
                "Active" if person["is_active"] else "Inactive",
                person["worker_type"], person["activity_type"], person["hire_date"],
                person["location"], person["location"], person["country"],
                person["is_active"], people_lead_eid, person["avatar_color"],
                person["created_at"] or now,
            ),
        )
        person_key[enterprise_id] = cursor.lastrowid
        person_stage[enterprise_id] = (
            person, people_lead_eid, full_name, level,
        )

    for key in capability_key.values():
        target.execute(
            """UPDATE dim_capability SET ManagingDirectorEID = ?
               WHERE CapabilityKey = ?""",
            ("oscar.r.punsalan", key),
        )

    legacy_skill_rows = rows(
        legacy,
        """SELECT ws.*, s.name AS skill_name
           FROM worker_skills ws JOIN skills s ON s.id = ws.skill_id
           ORDER BY ws.worker_id, ws.id""",
    )
    skill_names_by_person: dict[int, list[str]] = {}
    for skill in legacy_skill_rows:
        skill_names_by_person.setdefault(skill["worker_id"], []).append(skill["skill_name"])

    for person in workers:
        eid = person["employee_id"]
        primary_skill = legacy.execute(
            """SELECT s.name, ws.proficiency_level, ws.assessed_date
               FROM worker_skills ws JOIN skills s ON s.id = ws.skill_id
               WHERE ws.worker_id = ? AND ws.is_primary = 1 LIMIT 1""",
            (person["id"],),
        ).fetchone()
        skills_for_person = skill_names_by_person.get(person["id"], [])
        primary_skill_name = primary_skill["name"] if primary_skill else None
        secondary_skill_names = [
            name for name in skills_for_person if name != primary_skill_name
        ]
        target.execute(
            """INSERT INTO stg_headcount (
                   SourceFile, PersonnelNo, EnterpriseID, EmailAddress, Name,
                   Level, JobProfile, ProjectRole, EmploymentStatus, ResourceType,
                   ActivityType, JoinDate, HomeLoc, CurrLoc, Country, OrgLevel5,
                   OrgLevel6, OrgLevel7, OrgLevel8, BusinessGroup, Practice, Market,
                   MarketUnit, CapabilityMapping, CapabilityOwner, PrimarySkill,
                   SecondarySkill, ProficiencyLatest, LatestCycle, Project, Client,
                   Engagement, FTE, FTEPercent, ProjectStartDate, RollOffDate
               ) VALUES ({})""".format(",".join("?" for _ in range(36))),
            (
                "seed.py", person["worker_id"], eid, person["email"],
                person_stage[eid][2], person_stage[eid][3], person["job_profile"],
                None, "Active" if person["is_active"] else "Inactive",
                person["worker_type"], person["activity_type"], person["hire_date"],
                person["location"], person["location"], person["country"],
                person["org5"], person["supervisory_org"], None, None,
                person["business_group"], None, None, None,
                person["capability_area"], None,
                primary_skill_name, ", ".join(secondary_skill_names) or None,
                f"P{primary_skill['proficiency_level']}" if primary_skill else None,
                primary_skill["assessed_date"] if primary_skill else None,
                person["project"], person["client"], person["project"],
                person["fte"], round((person["fte"] or 0) * 100, 1),
                person["hire_date"], None,
            ),
        )

        if person["project"]:
            project_id = project_key[
                (person["project"], person["client"], person["industry_sector"])
            ]
            target.execute(
                """INSERT INTO bridge_person_project (
                       PersonKey, ProjectKey, FTE, FTEPercent,
                       ProjectStartDate, RollOffDate, IsPrimaryAllocation
                   ) VALUES (?,?,?,?,?,NULL,1)""",
                (
                    person_key[eid], project_id, person["fte"],
                    round((person["fte"] or 0) * 100, 1), person["hire_date"],
                ),
            )

    for skill in legacy_skill_rows:
        person = legacy_worker_by_id[skill["worker_id"]]
        target.execute(
            """INSERT INTO bridge_person_skill (
                   PersonKey, SkillKey, SkillType, ProficiencyCode, AssessmentCycle
               ) VALUES (?,?,?,?,?)""",
            (
                person_key[person["employee_id"]], skill_key[skill["skill_id"]],
                "Primary" if skill["is_primary"] else "Secondary",
                f"P{skill['proficiency_level']}", skill["assessed_date"],
            ),
        )

    training_records = rows(
        legacy,
        """SELECT wt.*, tc.short_code, tc.name AS course_name
           FROM worker_trainings wt JOIN training_catalog tc ON tc.id = wt.training_id
           ORDER BY wt.worker_id, wt.id""",
    )
    trainings_by_worker: dict[int, dict[str, str]] = {}
    for training in training_records:
        status = TRAINING_STATUS_MAP.get(training["status"], training["status"].title())
        completion_key = date_key(training["completion_date"])
        person = legacy_worker_by_id[training["worker_id"]]
        target.execute(
            """INSERT INTO fact_training_status (
                   PersonKey, CourseKey, Status, RegistrationStatus,
                   AttendanceStatus, CompletionDateKey, LatestEnrollmentFlag,
                   SourcePriority
               ) VALUES (?,?,?,?,?,?,1,1)""",
            (
                person_key[person["employee_id"]], course_key[training["training_id"]],
                status, None, None, completion_key,
            ),
        )
        trainings_by_worker.setdefault(training["worker_id"], {})[training["short_code"]] = status
        target.execute(
            """INSERT INTO stg_learning_enrollment (
                   ReferenceID, SourceFile, EnterpriseID, CourseCode, CourseName,
                   CompletionStatus, RegistrationStatus, CourseAttendanceStatus,
                   CompletionDate, LatestEnrollmentFlag
               ) VALUES (?,?,?,?,?,?,?,?,?,1)""",
            (
                f"seed2-{training['worker_id']}-{training['training_id']}",
                "seed.py", person["employee_id"], training["short_code"],
                training["course_name"], status, None, None,
                training["completion_date"],
            ),
        )

    certification_records = rows(
        legacy,
        """SELECT wc.*, c.code AS certification_code, c.name AS certification_name
           FROM worker_certifications wc JOIN certifications c ON c.id = wc.cert_id
           ORDER BY wc.worker_id, wc.id""",
    )
    certifications_by_worker: dict[int, list[sqlite3.Row]] = {}
    for certification in certification_records:
        person = legacy_worker_by_id[certification["worker_id"]]
        status = CERT_STATUS_MAP.get(certification["status"], certification["status"].title())
        target.execute(
            """INSERT INTO fact_certification (
                   PersonKey, CertificationCode, GoalStatus, TargetDateKey,
                   CompletionDateKey, ExpiryDateKey, EvidenceURL
               ) VALUES (?,?,?,?,?,?,NULL)""",
            (
                person_key[person["employee_id"]],
                certification["certification_code"], status,
                date_key(certification["goal_target_date"]),
                date_key(certification["earned_date"]),
                date_key(certification["expiry_date"]),
            ),
        )
        certifications_by_worker.setdefault(certification["worker_id"], []).append(certification)

    program_records = rows(
        legacy,
        """SELECT wp.*, p.code AS program_code, p.name AS program_name
           FROM worker_programs wp JOIN programs p ON p.id = wp.program_id
           ORDER BY wp.worker_id, wp.id""",
    )
    programs_by_worker: dict[int, dict[str, str]] = {}
    for program in program_records:
        person = legacy_worker_by_id[program["worker_id"]]
        status = PROGRAM_STATUS_MAP.get(program["status"], program["status"].title())
        mapped_code = program_key[program["program_id"]]
        status_date = program["completion_date"] or program["enrolled_date"]
        target.execute(
            """INSERT INTO fact_program_status (
                   PersonKey, ProgramCode, ProgramStatus, StatusDateKey, SourceFile
               ) VALUES (?,?,?,?,?)""",
            (
                person_key[person["employee_id"]], mapped_code, status,
                date_key(status_date), "seed.py",
            ),
        )
        programs_by_worker.setdefault(program["worker_id"], {})[program["program_code"]] = status
        if program["program_code"] == "RDE" and status != "Not Started":
            target.execute(
                """INSERT INTO stg_rde (
                       SourceFile, EnterpriseID, Name, RDEWorkshop, Cohort
                   ) VALUES (?,?,?,?,?)""",
                (
                    "seed.py", person["employee_id"],
                    f"{person['first_name']} {person['last_name']}",
                    status, None,
                ),
            )

    for person in workers:
        trainings = trainings_by_worker.get(person["id"], {})
        programs_for_person = programs_by_worker.get(person["id"], {})
        payload = {
            "trainings": trainings,
            "programs": programs_for_person,
            "source": "seed.py",
        }
        target.execute(
            """INSERT INTO stg_training_consolidated (
                   SourceFile, EnterpriseID, Name, FDETrainingStatus,
                   RDEWorkshopCompletion, ReinventionGarageCompleters,
                   GenAIStatus, AgenticAIStatus, RawPayload
               ) VALUES (?,?,?,?,?,?,?,?,?)""",
            (
                "seed.py", person["employee_id"],
                f"{person['first_name']} {person['last_name']}",
                programs_for_person.get("FDE"),
                programs_for_person.get("RDE"),
                programs_for_person.get("CLOUD_ELITE"),
                trainings.get("GENAI"), trainings.get("AGENTIC_L3A"),
                json.dumps(payload, sort_keys=True),
            ),
        )

    training_count = sum(
        1 for course in courses if course["category"] == "mandatory"
    )
    rules = [
        ("Training", 35.0, 80.0),
        ("Proficiency", 45.0, 60.0),
        ("Certification", 20.0, 50.0),
        ("Achievement", 0.0, None),
    ]
    for code, label, rank in [
        ("P1", "Foundational", 1), ("P2", "Working", 2),
        ("P3", "Proficient", 3), ("P4", "Expert", 4),
        ("P5", "Distinguished", 5),
    ]:
        target.execute(
            """INSERT INTO cfg_proficiency_rule (
                   ProficiencyCode, DisplayLabel, RankOrder, RuleVersion
               ) VALUES (?,?,?,?)""",
            (code, label, rank, RULE_VERSION),
        )
    for component, weight, threshold in rules:
        target.execute(
            """INSERT INTO cfg_ready_rule (
                   RuleVersion, ScoreComponent, ComponentWeight, Threshold,
                   MissingDataTreatment, CohortLogic, EffectiveFrom, EffectiveTo
               ) VALUES (?,?,?,?,?,?,?,NULL)""",
            (
                f"{RULE_VERSION}-{component}", component, weight, threshold,
                "zero", "capability", SNAPSHOT_DATE,
            ),
        )

    target.execute(
        """INSERT INTO cfg_training_applicability (
               CourseKey, PopulationRule, EffectiveFrom, EffectiveTo
           )
           SELECT CourseKey, ?, ?, NULL FROM dim_course WHERE Category = 'mandatory'""",
        ("population = 'all'", SNAPSHOT_DATE),
    )
    for course in courses:
        if course["category"] == "mandatory":
            continue
        target.execute(
            """INSERT INTO cfg_training_applicability (
                   CourseKey, PopulationRule, EffectiveFrom, EffectiveTo
               ) VALUES (?,?,?,NULL)""",
            (
                course_key[course["id"]],
                f"capability IN ({', '.join(repr(value) for value in capability_names)})",
                SNAPSHOT_DATE,
            ),
        )
    target.execute(
        """INSERT INTO cfg_helpful_link (
               LinkLabel, LinkURL, Audience, EffectiveFrom, EffectiveTo
           )
           SELECT CourseName, URL, 'all', ?, NULL FROM dim_course
           WHERE URL IS NOT NULL""",
        (SNAPSHOT_DATE,),
    )

    for person in workers:
        job = (person["job_profile"] or "").lower()
        if "capdev poc" in job or "capdev lead" in job:
            target.execute(
                """INSERT INTO cfg_portal_contact (
                       CapabilityKey, ContactRole, PersonKey, EffectiveFrom, EffectiveTo
                   ) VALUES (NULL,?,?,?,NULL)""",
                (
                    "CapDev Lead" if "lead" in job else "CapDev POC",
                    person_key[person["employee_id"]], SNAPSHOT_DATE,
                ),
            )

    today_key = date_key(date.today().isoformat())
    for person in workers:
        eid = person["employee_id"]
        primary = legacy.execute(
            """SELECT MAX(proficiency_level) FROM worker_skills
               WHERE worker_id = ? AND is_primary = 1""",
            (person["id"],),
        ).fetchone()[0] or 1
        prof_score = min((int(primary) - 1) * 10 + 5, 45)
        mandatory_completed = sum(
            record["status"] == "completed"
            for record in rows(
                legacy,
                """SELECT wt.status FROM worker_trainings wt
                   JOIN training_catalog tc ON tc.id = wt.training_id
                   WHERE wt.worker_id = ? AND tc.category = 'mandatory'""",
                person["id"],
            )
        )
        training_score = round(mandatory_completed / training_count * 35) if training_count else 0
        person_certs = certifications_by_worker.get(person["id"], [])
        cert_score = (
            20 if any(cert["status"] == "earned" for cert in person_certs)
            else 10 if any(cert["status"] == "in_progress" for cert in person_certs)
            else 0
        )
        ready_score = min(100, prof_score + training_score + cert_score)
        has_training_rows = person["id"] in trainings_by_worker
        completeness = round(
            100 * (int(primary > 0) + int(has_training_rows) + int(bool(person_certs))) / 3,
            1,
        )
        target.execute(
            """INSERT INTO fact_ready_snapshot (
                   PersonKey, SnapshotDateKey, RuleVersion, TrainingScore,
                   ProficiencyScore, CertificationScore, AchievementScore,
                   ReadyScore, DataCompletenessPercent, IsRankingEligible
               ) VALUES (?,?,?,?,?,?,?,?,?,?)""",
            (
                person_key[eid], today_key, RULE_VERSION, training_score,
                prof_score, cert_score, 0, ready_score, completeness,
                int(bool(person["is_active"])),
            ),
        )

    for row in rows(legacy, "SELECT * FROM checkins ORDER BY id"):
        worker = legacy_worker_by_id[row["worker_id"]]
        lead = legacy_worker_by_id[row["pl_id"]]
        target.execute(
            """INSERT INTO checkins (
                   worker_id, pl_id, checkin_type, notes, sentiment, checkin_date
               ) VALUES (?,?,?,?,?,?)""",
            (
                person_key[worker["employee_id"]], person_key[lead["employee_id"]],
                row["checkin_type"], row["notes"], row["sentiment"],
                row["checkin_date"],
            ),
        )

    for row in rows(legacy, "SELECT * FROM metric_snapshots ORDER BY id"):
        scope = row["scope"]
        if scope == "org":
            scope_type, scope_id = "org", "org"
        elif scope.startswith("capability:"):
            scope_type, scope_id = "capability", scope.removeprefix("capability:")
            if scope_id not in capability_key:
                continue
        elif scope.startswith("team:"):
            source_pl = legacy_worker_by_id.get(int(scope.split(":", 1)[1]))
            if not source_pl:
                continue
            scope_type, scope_id = "people_lead", source_pl["employee_id"]
        else:
            continue
        snapshot_date = f"{row['snapshot_month']}-01"
        target.execute(
            """INSERT OR IGNORE INTO fact_team_snapshot (
                   ScopeType, ScopeID, SnapshotDateKey, MetricKey, MetricValue
               ) VALUES (?,?,?,?,?)""",
            (scope_type, scope_id, date_key(snapshot_date), row["metric_key"], row["metric_value"]),
        )

    target_seed.seed_rbac(target, person_key)
    return person_key


def run(db_path: Path = DEFAULT_DB_PATH) -> None:
    if not SCHEMA_PATH.exists() or not COMPAT_PATH.exists():
        raise FileNotFoundError("CapDev schema or compatibility-view SQL is missing")
    with tempfile.TemporaryDirectory(prefix="capdev-seed-source-") as temp_dir:
        legacy_path = Path(temp_dir) / "ready_source.db"
        make_legacy_database(legacy_path)
        with closing(sqlite3.connect(legacy_path)) as legacy:
            legacy.row_factory = sqlite3.Row
            db_path.parent.mkdir(parents=True, exist_ok=True)
            with closing(sqlite3.connect(db_path)) as target:
                target.row_factory = sqlite3.Row
                target.executescript(SCHEMA_PATH.read_text(encoding="utf-8"))
                target.executescript(COMPAT_PATH.read_text(encoding="utf-8"))
                clear_target(target)
                person_key = seed_target(legacy, target)
                target.commit()
                target.execute("PRAGMA foreign_keys = ON")
                orphans = target.execute("PRAGMA foreign_key_check").fetchall()
                if orphans:
                    raise RuntimeError(f"Foreign-key check failed: {orphans[:10]}")
                print(f"Seeded CapDev database: {db_path}")
                print(f"  People: {len(person_key)}")
                for table in (
                    "bridge_person_skill", "fact_training_status",
                    "fact_program_status", "fact_certification",
                    "fact_ready_snapshot", "checkins",
                ):
                    count = target.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0]
                    print(f"  {table}: {count}")


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--db",
        type=Path,
        default=DEFAULT_DB_PATH,
        help=f"Target SQLite file (default: {DEFAULT_DB_PATH})",
    )
    args = parser.parse_args()
    run(args.db.resolve())


if __name__ == "__main__":
    main()
